#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v6.9 Pro Terminal - Complete All-in-One Installer
# 4 Live Architectural Themes (Obsidian / Linear / TV Pro / Bento HUD)
# + Live Server Hardware Telemetry (CPU / RAM / Disk / Load / Uptime)
# + Global Position Direction Mode (Smart Auto / LONG Only / SHORT Only)
# + Floating Bottom Glass Dock & 12-Col Bento HUD + Radial Gauges
# + Dedicated Backup Bot Token + kaviancrypto v4.2 Default Strategy
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v6.9 Pro - All-in-One Installer & Upgrade"
echo "  4 Themes (incl. Bento HUD) + Live Server Stats + Dir Mode"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

# Save a copy of this installer so Backup & Security tab can download it anytime
SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v6_9.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v6_9.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v6_9.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

